commits.message:
[turbofan] Calculate Int32Abs with no-branching approach

This change replace int32 absolute branching implementation with a no-branching approach using bitwise/cmov operations. The change improves WebXPRT4/PhotoEnhancement for ~4% and the following microbenchmark for 66% without regressing more predicable cases.

function func(a) { s = 0; for (var i = 0; i < 1000; i+=3) {
      var da = a[i] - 64;
      var db = a[i + 1] - 64;
      var dc = a[i + 2] - 64;
      var abs_a = da > 0 ? da: -da;
      var abs_b = db > 0 ? db: -db;
      var abs_c = dc > 0 ? dc: -dc;

      var diff = da;
      if (abs_b > abs_a) diff = db;
      if (abs_c > abs_a) diff = dc;

      s += diff;
    }
    return s;
}

var a = randomUint8ArrayInRange(0, 128, 3000)
for (var i = 0; i < 100000; i++) {
  func(a);
}

Change-Id: Id0c05ddcdbb4d8efe8aab08caaeaf1077a8573ea
Reviewed-on: https://chromium-review.googlesource.com/c/v8/v8/+/4368702
Reviewed-by: Tobias Tebbi <tebbi@chromium.org>
Commit-Queue: Fanchen Kong <fanchen.kong@intel.com>
Cr-Commit-Position: refs/heads/main@{#87181}

